// Mede 100 respostas 206 seguidas de um asset de 50 MB. `getContents` aloca o
// arquivo inteiro a cada chamada, como um backend sem leitura parcial (R-1).
const { H3, serveStatic } = await import("file:///C:/dev/runs/r14a2d37d00/src/index.ts");

const size = 50 * 1024 * 1024;
const app = new H3().all("/**", (event: any) =>
  serveStatic(event, {
    getContents: () => new Uint8Array(size),
    getMeta: () => ({ size, type: "video/mp4", etag: '"v1"' }),
  }),
);

let peakRss = process.memoryUsage().rss;
const started = performance.now();
for (let i = 0; i < 100; i++) {
  const start = i * 4096;
  const res = await app.request("/video.mp4", {
    headers: { range: `bytes=${start}-${start + 1_048_575}` },
  });
  if (res.status !== 206) throw new Error(`status ${res.status}`);
  await res.arrayBuffer();
  peakRss = Math.max(peakRss, process.memoryUsage().rss);
}
const elapsed = performance.now() - started;

console.log(`100 x 206 on 50 MB asset: ${elapsed.toFixed(0)} ms total, ${(elapsed / 100).toFixed(1)} ms/request`);
console.log(`peak RSS: ${(peakRss / 1024 / 1024).toFixed(0)} MB`);

